{
  "name": "csv-rfc4180",
  "version": "1.0.0",
  "description": "A dependency-free CSV parser, streaming parser and serializer",
  "main": "src/csv.js",
  "files": [
    "src"
  ],
  "scripts": {
    "test": "node --test test/*.test.js"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}
'use strict';

const LF = 10;
const CR = 13;
const SPACE = 32;
const QUOTE = 34;
const BOM = 0xfeff;

// Parser states.
const FIELD_START = 0; // nothing of the current field has been read yet
const UNQUOTED = 1; // inside a field that did not start with a quote
const QUOTED = 2; // inside a quoted field
const QUOTE_IN_QUOTED = 3; // read a quote in a quoted field: either the closing quote or the first of ""

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function checkOptions(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be an object');
  }
}

function getDelimiter(options) {
  const { delimiter } = options;
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError('delimiter must be a single character other than ", CR and LF');
  }
  return delimiter;
}

function toObject(columns, record) {
  const object = {};
  for (let k = 0; k < columns.length; k++) {
    if (columns[k] === '__proto__') {
      // Plain assignment would set the prototype instead of creating a key.
      Object.defineProperty(object, '__proto__', {
        value: record[k],
        writable: true,
        enumerable: true,
        configurable: true,
      });
    } else {
      object[columns[k]] = record[k];
    }
  }
  return object;
}

// The state machine shared by parse and createParser. write() consumes a chunk
// and end() the end of input; both return the records completed since the last
// call. Nothing is re-read: a field's text from earlier chunks is kept in
// `value` and the rest is sliced out of the current chunk when the field ends.
function createCore(options) {
  checkOptions(options);
  const delimiter = getDelimiter(options).charCodeAt(0);
  const headerMode = options.header === true;
  const skipEmptyLines = options.skipEmptyLines === true;

  let started = false; // whether any input has arrived, for the BOM
  let line = 1; // position of the next character
  let column = 1;
  let afterCR = false; // the previous character was a CR, so an LF now is part of its line break
  let state = FIELD_START;
  let value = ''; // text of the current field from earlier chunks
  let fields = []; // completed fields of the current record
  let recordLine = 1;
  let fieldLine = 1;
  let fieldColumn = 1;
  let columns = null; // header names, once the header record is complete
  let headerNames = headerMode ? new Set() : null; // names seen while reading the header record
  let records = [];

  function endField(text) {
    if (headerNames !== null) {
      if (headerNames.has(text)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(text)}`, fieldLine, fieldColumn);
      }
      headerNames.add(text);
    }
    fields.push(text);
  }

  function endRecord() {
    const record = fields;
    fields = [];
    if (!headerMode) {
      records.push(record);
    } else if (columns === null) {
      columns = record;
      headerNames = null;
    } else if (record.length !== columns.length) {
      throw new CsvError(
        `Expected ${columns.length} fields but found ${record.length}`,
        recordLine,
        1,
      );
    } else {
      records.push(toObject(columns, record));
    }
  }

  function take() {
    const completed = records;
    records = [];
    return completed;
  }

  function write(chunk) {
    const n = chunk.length;
    let i = 0;
    if (!started && n > 0) {
      started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    let segment = i; // where the current field's text not yet in `value` starts
    for (; i < n; i++) {
      const c = chunk.charCodeAt(i);
      switch (state) {
        case FIELD_START:
          if (c === LF && afterCR) {
            afterCR = false;
            continue;
          }
          if (fields.length === 0) recordLine = line;
          fieldLine = line;
          fieldColumn = column;
          if (c === QUOTE) {
            state = QUOTED;
            value = '';
            segment = i + 1;
          } else if (c === delimiter) {
            endField('');
          } else if (c === CR || c === LF) {
            // With no fields yet, this line is empty.
            if (fields.length > 0 || !skipEmptyLines) {
              endField('');
              endRecord();
            }
          } else {
            state = UNQUOTED;
            value = '';
            segment = i;
          }
          break;
        case UNQUOTED:
          if (c === delimiter) {
            endField(value + chunk.slice(segment, i));
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(value + chunk.slice(segment, i));
            endRecord();
            state = FIELD_START;
          }
          break;
        case QUOTED:
          if (c === QUOTE) {
            value += chunk.slice(segment, i);
            state = QUOTE_IN_QUOTED;
          }
          break;
        default: // QUOTE_IN_QUOTED
          if (c === QUOTE) {
            // An escaped quote: the second one starts the next run of text.
            state = QUOTED;
            segment = i;
          } else if (c === delimiter) {
            endField(value);
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(value);
            endRecord();
            state = FIELD_START;
          } else {
            throw new CsvError('Unexpected character after closing quote', line, column);
          }
      }
      if (c === CR) {
        line++;
        column = 1;
        afterCR = true;
      } else if (c === LF) {
        if (afterCR) {
          afterCR = false;
        } else {
          line++;
          column = 1;
        }
      } else {
        column++;
        afterCR = false;
      }
    }
    if (state === UNQUOTED || state === QUOTED) value += chunk.slice(segment, n);
    return take();
  }

  function end() {
    if (state === QUOTED) {
      throw new CsvError('Unclosed quoted field', fieldLine, fieldColumn);
    }
    if (state !== FIELD_START) {
      endField(value);
      endRecord();
    } else if (fields.length > 0) {
      // The input ends right after a delimiter: the last field is empty.
      fieldLine = line;
      fieldColumn = column;
      endField('');
      endRecord();
    }
    return take();
  }

  return { write, end };
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  const core = createCore(options);
  const records = core.write(text);
  for (const record of core.end()) records.push(record);
  return records;
}

function createParser(options = {}) {
  const core = createCore(options);
  let finished = false;

  function checkNotFinished() {
    if (finished) throw new Error('The parser has already finished');
  }

  return {
    write(chunk) {
      checkNotFinished();
      try {
        if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
        return core.write(chunk);
      } catch (error) {
        finished = true;
        throw error;
      }
    },
    end() {
      checkNotFinished();
      finished = true;
      return core.end();
    },
  };
}

function getEol(options) {
  const { eol } = options;
  if (eol === undefined) return '\r\n';
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError('eol must be "\\r\\n" or "\\n"');
  return eol;
}

function getHeader(options) {
  const { header } = options;
  if (header === undefined || header === null || header === false) return null;
  if (!Array.isArray(header)) throw new TypeError('header must be an array of column names');
  for (let k = 0; k < header.length; k++) {
    if (typeof header[k] !== 'string') throw new TypeError('column names must be strings');
  }
  return header;
}

function toText(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(`Cannot write a value of type ${typeof value}`);
}

function formatField(text, delimiter, forceQuote) {
  const n = text.length;
  let quote = forceQuote || (n > 0 && (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE));
  for (let k = 0; !quote && k < n; k++) {
    const c = text.charCodeAt(k);
    quote = c === delimiter || c === QUOTE || c === CR || c === LF;
  }
  return quote ? `"${text.replace(/"/g, '""')}"` : text;
}

function formatRecord(values, delimiter, atStart) {
  const n = values.length;
  const code = delimiter.charCodeAt(0);
  let out = '';
  for (let k = 0; k < n; k++) {
    const text = toText(values[k]);
    if (k > 0) {
      out += delimiter;
    } else if (n === 1 && text === '') {
      // Unquoted, this record would be an empty line.
      return '""';
    }
    // parse drops a BOM at the very start of the input, so the output must
    // not start with one.
    const forceQuote = atStart && k === 0 && (text.charCodeAt(0) === BOM || (text === '' && code === BOM));
    out += formatField(text, code, forceQuote);
  }
  return out;
}

function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  checkOptions(options);
  const delimiter = getDelimiter(options);
  const eol = getEol(options);
  const header = getHeader(options);
  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, true));
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = header.map((name) =>
        Object.prototype.hasOwnProperty.call(row, name) ? row[name] : undefined,
      );
    } else {
      throw new TypeError(
        header === null ? 'each row must be an array' : 'each row must be an array or an object',
      );
    }
    lines.push(formatRecord(values, delimiter, lines.length === 0));
  }
  return lines.length === 0 ? '' : lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

