];

const optionSets = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

test('gives the same result as parse for every split into up to three chunks', () => {
  for (const text of corpus) {
    for (const options of optionSets) {
      const expected = outcome(() => parse(text, options));
      const message = `${JSON.stringify(text)} with ${JSON.stringify(options)}`;
      assert.deepEqual(outcome(() => parseChunks([text], options)), expected, message);
      assert.deepEqual(outcome(() => parseChunks([...text], options)), expected, message);
      for (let i = 0; i <= text.length; i++) {
        for (let j = i; j <= text.length; j++) {
          const chunks = [text.slice(0, i), text.slice(i, j), text.slice(j)];
          assert.deepEqual(outcome(() => parseChunks(chunks, options)), expected, `${message} split at ${i}, ${j}`);
        }
      }
    }
  }
});

test('gives the same result as parse for random input and random chunks', () => {
  const rand = random(2);
  const alphabet = ['a', ',', '"', '"', '\r', '\n', ' ', '﻿'];
  for (let k = 0; k < 5000; k++) {
    const text = randomString(rand, alphabet, 40);
    const options = optionSets[k % optionSets.length];
    const chunks = [];
    let i = 0;
    while (i < text.length) {
      const size = Math.floor(rand() * 5);
      chunks.push(text.slice(i, i + size));
      i += size;
    }
    assert.deepEqual(
      outcome(() => parseChunks(chunks, options)),
      outcome(() => parse(text, options)),
      `${JSON.stringify(chunks)} with ${JSON.stringify(options)}`,
    );
  }
});

test('reports errors at the same positions as parse', () => {
  const chunks = ['a,b\r', '\n1,2\r', '\n"x\r', '\ny"', '"', '"', 'z'];
  const text = chunks.join('');
  assert.throws(() => parse(text), (error) => error.line === 4 && error.column === 5);
  const parser = createParser();
  const records = [];
  assert.throws(
    () => {
      for (const chunk of chunks) records.push(...parser.write(chunk));
    },
    (error) => error instanceof CsvError && error.line === 4 && error.column === 5,
  );
  assert.deepEqual(records, [['a', 'b'], ['1', '2']]);
});

test('time stays linear in the input for tiny chunks', () => {
  const size = 1_000_000;
  const inputs = [
    `"${'x'.repeat(size)}"`, // one long quoted field
    'y'.repeat(size), // one long unquoted field
    'a,b\r\n'.repeat(size / 5), // many short records
    `"${'""'.repeat(size / 2)}"`, // many escaped quotes
  ];
  for (const text of inputs) {
    const startedAt = process.hrtime.bigint();
    const parser = createParser();
    let count = 0;
    for (let i = 0; i < text.length; i++) count += parser.write(text[i]).length;
    count += parser.end().length;
    const seconds = Number(process.hrtime.bigint() - startedAt) / 1e9;
    assert.equal(count, parse(text).length);
    assert.ok(seconds < 5, `took ${seconds}s for ${text.length} one-character chunks`);
  }
});

