'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv');
const { random, randomString, outcome, referenceParse } = require('./helpers');

function assertCsvError(fn, line, column) {
  assert.throws(fn, (error) => {
    assert.ok(error instanceof CsvError, `expected a CsvError, got ${error}`);
    assert.ok(error instanceof Error);
    assert.equal(error.name, 'CsvError');
    assert.deepEqual({ line: error.line, column: error.column }, { line, column });
    return true;
  });
}

test('text must be a string', () => {
  for (const text of [undefined, null, 1, true, {}, [], Buffer.from('a,b')]) {
    assert.throws(() => parse(text), TypeError);
  }
});

test('empty input gives no records', () => {
  assert.deepEqual(parse(''), []);
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('﻿'), []);
});

test('splits fields and records', () => {
  assert.deepEqual(parse('a,b,c\n1,2,3'), [
    ['a', 'b', 'c'],
    ['1', '2', '3'],
  ]);
  assert.deepEqual(parse('a'), [['a']]);
  assert.deepEqual(parse(',,'), [['', '', '']]);
  assert.deepEqual(parse('a,\n,b'), [
    ['a', ''],
    ['', 'b'],
  ]);
});

test('records may have different lengths without a header', () => {
  assert.deepEqual(parse('a\nb,c\nd,e,f'), [['a'], ['b', 'c'], ['d', 'e', 'f']]);
});

test('accepts CRLF, LF and CR line breaks, mixed', () => {
  assert.deepEqual(parse('a\r\nb\nc\rd\n\re'), [['a'], ['b'], ['c'], ['d'], [''], ['e']]);
  assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
  assert.deepEqual(parse('a\n\r\nb'), [['a'], [''], ['b']]);
});

test('uses a custom delimiter', () => {
  assert.deepEqual(parse('a;b,c\n"x;y";z', { delimiter: ';' }), [
    ['a', 'b,c'],
    ['x;y', 'z'],
  ]);
  assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
  assert.deepEqual(parse('a  b', { delimiter: ' ' }), [['a', '', 'b']]);
  assert.deepEqual(parse('xaybz', { delimiter: 'a' }), [['x', 'ybz']]);
});

test('rejects invalid delimiters', () => {
  for (const delimiter of ['', ',,', '"', '\r', '\n', '\r\n', '😀', null, 1, [','], {}]) {
    assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
  }
});

test('rejects options that are not an object', () => {
  assert.throws(() => parse('a', null), TypeError);
  assert.throws(() => parse('a', 'x'), TypeError);
});

test('ignores a leading byte order mark only', () => {
  assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
  assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
  assert.deepEqual(parse('a,﻿b\n﻿c'), [
    ['a', '﻿b'],
    ['﻿c'],
  ]);
  assert.deepEqual(parse('﻿"a,b"'), [['a,b']]);
  assert.deepEqual(parse('﻿a,b\n1,2', { header: true }), [{ a: '1', b: '2' }]);
  assert.deepEqual(parse('﻿\n'), [['']]);
});

test('the byte order mark does not count as a column', () => {
  assertCsvError(() => parse('﻿"a"x'), 1, 4);
});

test('quoted fields keep delimiters, line breaks and escaped quotes', () => {
  assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh","i""j"'), [
    ['a,b', 'c\nd', 'e\r\nf', 'g\rh', 'i"j'],
  ]);
  assert.deepEqual(parse('""'), [['']]);
  assert.deepEqual(parse('""""'), [['"']]);
  assert.deepEqual(parse('"",""'), [['', '']]);
  assert.deepEqual(parse('"a"\n"b"\r\n"c"\r"d"'), [['a'], ['b'], ['c'], ['d']]);
  assert.deepEqual(parse('"\n"'), [['\n']]);
});

test('a quote inside an unquoted field is an ordinary character', () => {
  assert.deepEqual(parse('a"b,c",d""'), [['a"b', 'c"', 'd""']]);
  assert.deepEqual(parse(' "a"'), [[' "a"']]);
});

test('keeps whitespace exactly', () => {
  assert.deepEqual(parse(' a , b\t,\t\n  '), [
    [' a ', ' b\t', '\t'],
    ['  '],
  ]);
  assert.deepEqual(parse('" a "'), [[' a ']]);
});

test('one final line break does not start a record', () => {
  assert.deepEqual(parse('a\n'), [['a']]);
  assert.deepEqual(parse('a\r\n'), [['a']]);
  assert.deepEqual(parse('a\r'), [['a']]);
  assert.deepEqual(parse('a,\n'), [['a', '']]);
  assert.deepEqual(parse('"a\n"\n'), [['a\n']]);
});

test('every other empty line is a record with one empty field', () => {
  assert.deepEqual(parse('\n'), [['']]);
  assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
  assert.deepEqual(parse('\na\n\nb'), [[''], ['a'], [''], ['b']]);
});

test('skipEmptyLines skips empty lines only', () => {
  const options = { skipEmptyLines: true };
  assert.deepEqual(parse('\n\r\na\n\n\rb\n\n', options), [['a'], ['b']]);
  assert.deepEqual(parse('\n', options), []);
  assert.deepEqual(parse('""\n \n,\n"\n"', options), [[''], [' '], ['', ''], ['\n']]);
});

test('header mode returns objects keyed by the first record', () => {
  assert.deepEqual(parse('name,age\nAda,36\r\n"Lin, J",\n', { header: true }), [
    { name: 'Ada', age: '36' },
    { name: 'Lin, J', age: '' },
  ]);
  const [record] = parse('b,a\n1,2', { header: true });
  assert.deepEqual(Object.keys(record), ['b', 'a']);
});

test('header mode with only a header gives no records', () => {
  assert.deepEqual(parse('a,b', { header: true }), []);
  assert.deepEqual(parse('a,b\n', { header: true }), []);
  assert.deepEqual(parse('\n\na,b\n\n', { header: true, skipEmptyLines: true }), []);
});

test('header mode and empty lines', () => {
  assert.deepEqual(parse('\na\n\nb', { header: true, skipEmptyLines: true }), [{ a: 'b' }]);
  assert.deepEqual(parse('a\n\nb', { header: true }), [{ a: '' }, { a: 'b' }]);
  assert.deepEqual(parse('\n\nb', { header: true }), [{ '': '' }, { '': 'b' }]);
  assertCsvError(() => parse('a,b\n1,2\n\n3,4', { header: true }), 3, 1);
  assert.deepEqual(parse('a,b\n1,2\n\n3,4', { header: true, skipEmptyLines: true }), [
    { a: '1', b: '2' },
    { a: '3', b: '4' },
  ]);
});

test('header names that are Object.prototype properties become own keys', () => {
  const [record] = parse('__proto__,constructor,toString\n1,2,3', { header: true });
  assert.equal(Object.getPrototypeOf(record), Object.prototype);
  assert.deepEqual(Object.keys(record), ['__proto__', 'constructor', 'toString']);
  assert.equal(record.constructor, '2');
  assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, '1');
});

test('duplicate header names are an error at the second field', () => {
  assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5);
  assertCsvError(() => parse('a,"b\nc","b\nc"', { header: true }), 2, 4);
  assertCsvError(() => parse(',', { header: true }), 1, 2);
  assertCsvError(() => parse('x,,', { header: true }), 1, 4);
  assertCsvError(() => parse('\n\na,a', { header: true, skipEmptyLines: true }), 3, 3);
  // Only the header is checked.
  assert.deepEqual(parse('a,b\n1,1', { header: true }), [{ a: '1', b: '1' }]);
});

test('a record with the wrong number of fields is an error in header mode', () => {
  assertCsvError(() => parse('a,b\n1,2\n1,2,3', { header: true }), 3, 1);
  assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
  assertCsvError(() => parse('a,b\n"1\n1"\n', { header: true }), 2, 1);
  assertCsvError(() => parse('a,b\r\n1,2\r\n1,2,', { header: true }), 3, 1);
});

test('an unclosed quoted field is an error at its opening quote', () => {
  assertCsvError(() => parse('"abc'), 1, 1);
  assertCsvError(() => parse('a,"b'), 1, 3);
  assertCsvError(() => parse('a\nb,"c\n\nd'), 2, 3);
  assertCsvError(() => parse('"a""'), 1, 1);
  assertCsvError(() => parse('"'), 1, 1);
});

test('a character after a closing quote is an error at that character', () => {
  assertCsvError(() => parse('"a"b'), 1, 4);
  assertCsvError(() => parse('"a" ,b'), 1, 4);
  assertCsvError(() => parse('x,"a"""b'), 1, 8);
  assertCsvError(() => parse('"a";b', { delimiter: ',' }), 1, 4);
  assert.deepEqual(parse('"a";b', { delimiter: ';' }), [['a', 'b']]);
});

test('lines count every line break, including inside quoted fields', () => {
  assertCsvError(() => parse('a\r\nb\rc\nd\r\n\r\n"x"y'), 6, 4);
  assertCsvError(() => parse('"a\r\nb\rc\nd"e'), 4, 3);
  assertCsvError(() => parse('"\r\n\n\r"x'), 4, 2);
});

test('columns count UTF-16 code units', () => {
  assertCsvError(() => parse('😀,"é"x'), 1, 7);
  assertCsvError(() => parse('a\n😀😀,"'), 2, 6);
});

test('the first error in reading order is thrown', () => {
  // A duplicate name comes before a later unclosed quote.
  assertCsvError(() => parse('a,a,"b', { header: true }), 1, 3);
  // A bad character after a quote comes before the duplicate is complete.
  assertCsvError(() => parse('a,"a"x', { header: true }), 1, 6);
  // Field counts are checked when the record ends...
  assertCsvError(() => parse('a,b\n1,2,3\n"x', { header: true }), 2, 1);
  // ...so an error inside the record comes first.
  assertCsvError(() => parse('a,b\n1,2,"x"y', { header: true }), 2, 8);
  assertCsvError(() => parse('a,b\n1,2,"x', { header: true }), 2, 5);
  assertCsvError(() => parse('"a"b\n"c'), 1, 4);
});

test('agrees with the reference implementation on random input', () => {
  const rand = random(1);
  const alphabet = ['a', 'b', ',', ';', '"', '"', '\r', '\n', ' ', '\t', '#', '﻿', '😀'];
  const optionSets = [
    {},
    { trim: true },
    { comment: '#' },
    { trim: true, comment: '#', header: true },
    { trim: true, comment: '#', skipEmptyLines: true, delimiter: ';' },
    { trim: true, delimiter: '\t' },
    { comment: ' ', trim: true },
    { skipEmptyLines: true },
    { header: true },
    { header: true, skipEmptyLines: true },
    { delimiter: ';' },
    { delimiter: ';', header: true },
  ];
  for (let k = 0; k < 20000; k++) {
    const text = randomString(rand, alphabet, 24);
    const options = optionSets[k % optionSets.length];
    assert.deepEqual(
      outcome(() => parse(text, options)),
      outcome(() => referenceParse(text, options)),
      `${JSON.stringify(text)} with ${JSON.stringify(options)}`,
    );
  }
});

test('trim removes spaces and tabs around unquoted fields only', () => {
  assert.deepEqual(parse(' a ,\t b\t\t,c d ', { trim: true }), [['a', 'b', 'c d']]);
  assert.deepEqual(parse(' a ,b', { trim: false }), [[' a ', 'b']]);
  assert.deepEqual(parse(' a ,b'), [[' a ', 'b']]);
  assert.deepEqual(parse(' , \t ,\n \t ', { trim: true }), [['', '', ''], ['']]);
  assert.deepEqual(parse('a\u00a0,\r\n', { trim: true }), [['a\u00a0', '']]);
  assert.deepEqual(parse('a "b" ,c"d" ', { trim: true }), [['a "b"', 'c"d"']]);
});

test('trim allows spaces and tabs around a quoted field and keeps its content', () => {
  assert.deepEqual(parse(' \t" a ""b"" ,\n"\t ,\t " \t"\t ,x', { trim: true }), [[' a "b" ,\n', ' \t', 'x']]);
  assert.deepEqual(parse('  "a"  \n\t"b"\t', { trim: true }), [['a'], ['b']]);
  assert.deepEqual(parse(' "a"\r\n "b" \r "c" ', { trim: true }), [['a'], ['b'], ['c']]);
  assert.deepEqual(parse('""  ,  ""', { trim: true }), [['', '']]);
});

test('without trim, spaces around a quoted field are an error or ordinary text', () => {
  assertCsvError(() => parse('"a" ,b'), 1, 4);
  assert.deepEqual(parse(' "a",b'), [[' "a"', 'b']]);
});

test('trim still rejects other characters around a quoted field', () => {
  assertCsvError(() => parse('"a" x', { trim: true }), 1, 5);
  assertCsvError(() => parse('"a"  "b"', { trim: true }), 1, 6);
  assertCsvError(() => parse('"a"\u00a0', { trim: true }), 1, 4);
  assert.deepEqual(parse(' x"a"', { trim: true }), [['x"a"']]);
});

test('a delimiter that is a space or a tab is never trimmed', () => {
  assert.deepEqual(parse(' a\t\t b\t', { trim: true, delimiter: '\t' }), [['a', '', 'b', '']]);
  assert.deepEqual(parse('a  "b" ', { trim: true, delimiter: ' ' }), [['a', '', 'b', '']]);
});

test('trim applies to header names and a whitespace-only line is not empty', () => {
  assert.deepEqual(parse(' x , "y" \n 1 , 2 \n', { trim: true, header: true }), [{ x: '1', y: '2' }]);
  assertCsvError(() => parse('x, x \n', { trim: true, header: true }), 1, 2);
  assertCsvError(() => parse('x,y\n1, 2, 3', { trim: true, header: true }), 2, 1);
  assert.deepEqual(parse('a\n \n\nb', { trim: true, skipEmptyLines: true }), [['a'], [''], ['b']]);
});

test('errors point at the first character of a field, including trimmed spaces', () => {
  assertCsvError(() => parse('a, "b', { trim: true }), 1, 3);
  assertCsvError(() => parse('a,b\n  "b', { trim: true }), 2, 1);
});

test('a comment line is skipped with its line break', () => {
  assert.deepEqual(parse('#a\nb\n#c\r\nd\r#e\r\n#f', { comment: '#' }), [['b'], ['d']]);
  assert.deepEqual(parse('#a,"b\n#\n\n#', { comment: '#' }), [['']]);
  assert.deepEqual(parse('#', { comment: '#' }), []);
  assert.deepEqual(parse('\ufeff#a\nb', { comment: '#' }), [['b']]);
  assert.deepEqual(parse('#a\nb', { comment: '#' }), [['b']]);
  assert.deepEqual(parse('#a\nb'), [['#a'], ['b']]);
});

test('the comment character is ordinary anywhere else', () => {
  assert.deepEqual(parse('a#,#b\n"#",\n"x\n#y"\n ,#', { comment: '#' }), [
    ['a#', '#b'],
    ['#', ''],
    ['x\n#y'],
    [' ', '#'],
  ]);
  assert.deepEqual(parse(' #a', { comment: '#' }), [[' #a']]);
  assert.deepEqual(parse(' #a', { comment: '#', trim: true }), [['#a']]);
  assert.deepEqual(parse('a\n#b\n', { comment: '#' }), [['a']]);
});

test('a comment line is not an empty line and does not count as a record', () => {
  assert.deepEqual(parse('#a\n\n#b\n', { comment: '#' }), [['']]);
  assert.deepEqual(parse('#a\n\n#b\n', { comment: '#', skipEmptyLines: true }), []);
  assert.deepEqual(parse('#c\nx,y\n#d\n1,2\n#e', { comment: '#', header: true }), [{ x: '1', y: '2' }]);
});

test('a comment character may be a space, a letter or a tab', () => {
  assert.deepEqual(parse(' a\nb \n', { comment: ' ' }), [['b ']]);
  assert.deepEqual(parse('xa\nb', { comment: 'x' }), [['b']]);
  assert.deepEqual(parse('\ta\nb', { comment: '\t', trim: true }), [['b']]);
});

test('line numbers in errors count comment lines', () => {
  assertCsvError(() => parse('#a\n#b\r\n#c\rx,"y', { comment: '#' }), 4, 3);
  assertCsvError(() => parse('#a\nx,y\n#b\n1', { comment: '#', header: true }), 4, 1);
  assertCsvError(() => parse('#a\nx,x\n', { comment: '#', header: true }), 2, 3);
  assertCsvError(() => parse('#a\n"b"c', { comment: '#' }), 2, 4);
});

test('rejects invalid comment characters', () => {
  for (const comment of ['', '##', '"', '\r', '\n', ',', 1, null, true, {}, '😀']) {
    assert.throws(() => parse('a', { comment }), TypeError, String(comment));
  }
  assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
  assert.throws(() => parse('a', { comment: '\t', delimiter: '\t' }), TypeError);
  assert.deepEqual(parse('a', { comment: undefined }), [['a']]);
});
